import { computed, ref } from "vue";
import {
  XhDateFieldControl,
  XhDateFieldLabel,
  XhDateFieldRoot,
  XhDateFieldSegment,
} from "@xihan-ui/vue";

// 宿主与后端约定的写法
const stored = ref("2026/07/28");

// 读时换成 ISO 交给组件，写回时换回宿主的写法
const iso = computed<string | null>({
  get: () => (stored.value ? stored.value.split("/").join("-") : null),
  set: (next) => {
    stored.value = next ? next.split("-").join("/") : "";
  },
});
